llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Pethidine, the structurally closest analogue sharing an N-methylpiperidine and ester motif, has an absolute oral bioavailability of 0.57 ± 0.13 in normal subjects, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Solifenacin, another antimuscarinic with a basic amine and ester-like carbamate, has a high absolute oral bioavailability of 88% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Netupitant, a lipophilic tertiary amine with high absolute bioavailability of 63–87% in humans, supports a high F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ketanserin, a piperidine-containing drug, has an absolute oral bioavailability of 55.5 ± 8.7% in healthy subjects, well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Silodosin, a basic amine drug with an absolute bioavailability of 32.2% in healthy men, is above the 20% threshold and supports high F despite moderate first-pass effects.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability above 20%, ranging from about 30% to 90%. The structurally closest analogue pethidine has F ≈ 50%, and the pharmacologically related antimuscarinic solifenacin has F ≈ 88%. No transferable evidence supports F < 20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is provided.",
    "The metabolic stability of the ester group and the extent of first-pass hydrolysis are not directly assessed in the evidence.",
    "Some analogues have lower F values (~30–35%), but all remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

